import {readFile,readdir,lstat,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {resolve} from 'node:path';
import {PROFILE} from '../../../dist/src/profile.js';
const root=new URL('./evidence/',import.meta.url),manifest=JSON.parse(await readFile(new URL('engineering-manifest.json',root),'utf8')),sha=x=>createHash('sha256').update(x).digest('hex');
const actual={};async function walk(path){for(const e of await readdir(path,{withFileTypes:true})){const p=path+'/'+e.name;if(e.isDirectory())await walk(p);else{if(!e.isFile())throw Error('Nonregular payload');actual[p]=sha(await readFile(p));}}}
for(const d of ['dist','packages/contracts/dist','packages/ai-gateway/dist','packages/asset-core/dist','packages/material-processing/dist','packages/image-adapter/dist','packages/mz-compiler/dist','packages/pack-assembly/dist','packages/persistence/dist','packages/local-executor/dist','packages/pack-export/dist','apps/api/dist','apps/web/dist','apps/api/prisma/migrations'])await walk(d);
actual['apps/api/prisma/schema.prisma']=sha(await readFile('apps/api/prisma/schema.prisma'));
const files=Object.fromEntries(Object.keys(actual).sort().map(k=>[k,actual[k]]));
const identity={commit:execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),profile:PROFILE,pixelContract:PROFILE.pixelContract,httpContract:'http-v1',taskContract:'task-snapshot-v1',domainContract:'asset-revision-v1',irContract:'tile-ir-v1',processing:'fixed-shoreline-v1',fragmentContract:'mz-compiled-fragment-v1',compiler:'mz-single-material-v1',packContract:'mz-pack-v1',layoutContract:'mz-layout-v1',assembly:'stable-slots-v1',persistence:'durable-store-v1',executor:'local-executor-v1',schemaSha256:sha(await readFile('apps/api/prisma/schema.prisma')),studio:'manual-studio-v1',standardExport:'mz-pack-build-v1',pngHttpIngress:'studio-png-http-v1',previewClock:'fixed-logical-updates-v1',node:process.versions.node,pnpm:'10.20.0',lockSha256:sha(await readFile('pnpm-lock.yaml')),files};
const id='step07-'+identity.commit.slice(0,12)+'-'+sha(JSON.stringify(identity)).slice(0,16);if(id!==manifest.buildId)throw Error('Independent engineering identity mismatch');
const parent=JSON.parse(await readFile('/Users/dingshinn/Desktop/rpg-maker-maker/docs/evidence/step-07/independent-round12/evidence/engineering-manifest.json','utf8'));const changes=Object.keys(files).filter(k=>files[k]!==parent.files[k]);if(JSON.stringify(changes)!==JSON.stringify(['apps/api/dist/resources/studio.json']))throw Error('Unexpected production changes');
const author='/Users/dingshinn/.codex/worktrees/step-07-studio/rpg-maker-maker';const oldLedger=JSON.parse(execFileSync('git',['show','428d981925bc265527b32409f51f9cc5cc149c8c:docs/evidence/step-07/r11-browser-order/ledger.json'],{encoding:'utf8'}));const oldResource=JSON.parse(await readFile(resolve(author,oldLedger.build.manifestPath,'../apps/api/dist/resources/studio.json'),'utf8'));const now=JSON.parse(await readFile('apps/api/dist/resources/studio.json','utf8'));const commits={before:oldResource.context.commit,after:now.context.commit};delete oldResource.context.commit;delete now.context.commit;if(JSON.stringify(now)!==JSON.stringify(oldResource))throw Error('studio content differs');
const canonical=x=>Array.isArray(x)?x.map(canonical):x&&typeof x==='object'?Object.fromEntries(Object.keys(x).sort().map(k=>[k,canonical(x[k])])):x;
const result={source:identity.commit,buildId:id,actualPayloads:Object.keys(files).length,manifestSHA256:sha(await readFile(new URL('engineering-manifest.json',root))),profileSHA256:sha(JSON.stringify(canonical(PROFILE))),parentBuild:parent.buildId,unchangedPayloads:205,changed:changes,studioChangeOnlyContextCommit:commits,independentlyCollectedActualTree:true,engineeringPublication:'NOT_EXECUTED_NO_DIRECTORY_PUBLISHED'};
await writeFile(new URL('engineering-identity-independent.json',root),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result));
